import hashlib
import os
import time
import uuid
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class User:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    username: str = ""
    email: str = ""
    password_hash: str = ""
    role: str = "user"
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    is_active: bool = True

    def to_dict(self):
        return {
            "id": self.id,
            "username": self.username,
            "email": self.email,
            "role": self.role,
            "created_at": self.created_at,
            "updated_at": self.updated_at,
            "is_active": self.is_active,
        }


class UserStore:
    def __init__(self):
        self._users: dict[str, User] = {}

    def create(self, username: str, email: str, password: str, role: str = "user") -> User:
        user = User(
            username=username,
            email=email,
            password_hash=_hash_password(password),
            role=role,
        )
        self._users[user.id] = user
        return user

    def get_by_id(self, user_id: str) -> Optional[User]:
        return self._users.get(user_id)

    def get_by_username(self, username: str) -> Optional[User]:
        for user in self._users.values():
            if user.username == username:
                return user
        return None

    def get_by_email(self, email: str) -> Optional[User]:
        for user in self._users.values():
            if user.email == email:
                return user
        return None

    def list_all(self) -> list[User]:
        return list(self._users.values())

    def update(self, user_id: str, **kwargs) -> Optional[User]:
        user = self._users.get(user_id)
        if user is None:
            return None
        allowed = {"username", "email", "role", "is_active"}
        for key, value in kwargs.items():
            if key in allowed:
                setattr(user, key, value)
        if "password" in kwargs:
            user.password_hash = _hash_password(kwargs["password"])
        user.updated_at = time.time()
        return user

    def delete(self, user_id: str) -> bool:
        if user_id in self._users:
            del self._users[user_id]
            return True
        return False

    def verify_password(self, user: User, password: str) -> bool:
        return user.password_hash == _hash_password(password)

    def clear(self):
        self._users.clear()


def _hash_password(password: str) -> str:
    salt = os.environ.get("PASSWORD_SALT", "default-salt")
    return hashlib.sha256(f"{salt}:{password}".encode()).hexdigest()


user_store = UserStore()

import jwt
from flask import current_app


def create_access_token(user_id: str, role: str) -> str:
    app = current_app._get_current_object()
    payload = {"sub": user_id, "role": role, "type": "access"}
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm=app.config["JWT_ALGORITHM"])


def create_refresh_token(user_id: str, role: str) -> str:
    app = current_app._get_current_object()
    payload = {"sub": user_id, "role": role, "type": "refresh"}
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm=app.config["JWT_ALGORITHM"])


def decode_token(token: str) -> dict:
    app = current_app._get_current_object()
    return jwt.decode(token, app.config["SECRET_KEY"], algorithms=[app.config["JWT_ALGORITHM"]])

from marshmallow import Schema, fields, validate, validates_schema, ValidationError


class LoginSchema(Schema):
    username = fields.String(required=True, validate=validate.Length(min=1, max=80))
    password = fields.String(required=True, validate=validate.Length(min=1))


class RefreshSchema(Schema):
    refresh_token = fields.String(required=True)


class CreateUserSchema(Schema):
    username = fields.String(
        required=True, validate=validate.Length(min=3, max=80)
    )
    email = fields.Email(required=True)
    password = fields.String(
        required=True, validate=validate.Length(min=6, max=128)
    )
    role = fields.String(
        validate=validate.OneOf(["user", "admin"]), missing="user"
    )


class UpdateUserSchema(Schema):
    username = fields.String(validate=validate.Length(min=3, max=80))
    email = fields.Email()
    password = fields.String(validate=validate.Length(min=6, max=128))
    role = fields.String(validate=validate.OneOf(["user", "admin"]))
    is_active = fields.Boolean()

    @validates_schema
    def validate_at_least_one(self, data, **kwargs):
        if not data:
            raise ValidationError("At least one field must be provided")


class CreateUserSchemaV2(CreateUserSchema):
    display_name = fields.String(validate=validate.Length(max=120))


class UpdateUserSchemaV2(UpdateUserSchema):
    display_name = fields.String(validate=validate.Length(max=120))

from functools import wraps
from flask import request, g
from marshmallow import ValidationError

from ..utils.token import decode_token, create_access_token, create_refresh_token


def require_auth(f):
    def _require_auth(*args, **kwargs):
        return _authenticate(f, required=True)(*args, **kwargs)
    return _require_auth


def optional_auth(f):
    def _optional_auth(*args, **kwargs):
        return _authenticate(f, required=False)(*args, **kwargs)
    return _optional_auth


def _authenticate(view_func, required):
    @wraps(view_func)
    def wrapper(*args, **kwargs):
        g.current_user = None
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            if required:
                return {"error": "Missing or invalid Authorization header", "code": "UNAUTHORIZED"}, 401
            return view_func(*args, **kwargs)

        token = auth_header[7:]
        try:
            payload = decode_token(token)
            if payload.get("type") != "access":
                return {"error": "Invalid token type", "code": "INVALID_TOKEN_TYPE"}, 401
            g.current_user_id = payload["sub"]
            g.current_user_role = payload["role"]
        except Exception:
            if required:
                return {"error": "Invalid or expired token", "code": "INVALID_TOKEN"}, 401
            return view_func(*args, **kwargs)

        return view_func(*args, **kwargs)

    return wrapper

import time
from functools import wraps
from flask import request, g, current_app


_rate_store: dict[str, list[float]] = {}


def rate_limit(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        key = _build_key()
        max_req = current_app.config.get("RATE_LIMIT_REQUESTS", 100)
        window = current_app.config.get("RATE_LIMIT_WINDOW", 60)

        now = time.monotonic()
        timestamps = _rate_store.get(key, [])
        timestamps = [t for t in timestamps if now - t < window]
        _rate_store[key] = timestamps

        if len(timestamps) >= max_req:
            retry_after = int(window - (now - timestamps[0]))
            return {
                "error": "Rate limit exceeded",
                "code": "RATE_LIMITED",
                "retry_after": retry_after,
            }, 429

        _rate_store[key].append(now)
        return f(*args, **kwargs)

    return wrapper


def _build_key() -> str:
    user_id = getattr(g, "current_user_id", None)
    if user_id:
        return f"user:{user_id}"
    return f"ip:{request.remote_addr}"


def _clear_rate_store():
    _rate_store.clear()

